Given the head of a singly linked list, determine whether the list contains a cycle. A cycle exists if, while traversing the list through next pointers, you encounter a node that has already been visited instead of eventually reaching nullptr.Examples:Input: head: 1 -> 3 -> 4 -> 3Output: true Explanation: The last node of the linked list does not point to NULL; instead, it points to an earlier node in the list, creating a cycle.Input: head: 1 -> 8 -> 3 -> 4 -> NULL Output: false Explanation: The last node of the linked list points to NULL, indicating the end of the list.Try It YourselfTable of Content[Naive Approach] Using HashSet - O(n) Time and O(n) Space[Expected Approach] Using Floyd's Cycle-Finding Algorithm[Naive Approach] Using HashSet - O(n) Time and O(n) SpaceThe idea is to insert the nodes in the Hashset while traversing and whenever a node is encountered that is already present in the hashset (which indicates there's a cycle (loop) in the list) then return true. If  the node is NULL, represents the end of Linked List, return false as there is no loop.
            C++

    //Driver Code Starts
#include <iostream>
#include <unordered_set>
using namespace std;

//Driver Code Ends

class Node {
public:
    int data;
    Node* next;
    Node(int x) {
        this->data = x;
        this->next = nullptr;
    }
};

bool detectLoop(Node* head) {
    unordered_set<Node*>st;

    while (head != nullptr) {

        // if this node is already present
        // in hashmap it means there is a cycle
        if (st.find(head) != st.end())
            return true;

        // if we are seeing the node for
        // the first time, insert it in hash
        st.insert(head);

        head = head->next;
    }
    return false;
}

//Driver Code Starts

int main() {

    Node* head = new Node(1);
    head->next = new Node(3);
    head->next->next = new Node(4);

    head->next->next->next = head->next;

    if (detectLoop(head))
        cout << "true";
    else
        cout << "false";

    return 0;
}
